function _update() {
  // camera: left / right turn around the tower, up / down raise and lower it
  if (btn(0)) ang -= 0.005
  if (btn(1)) ang += 0.005
  if (btn(2)) lift = min(lift + 0.003, 0.2)
  if (btn(3)) lift = max(lift - 0.003, 0.01)

  if (over) {
    hover = []
    if (btnp(4) || btnp(5) || btnp(19)) { newGame(); sfx(4) }
  } else {
    // the block under the cursor: a ray from the camera, then the first block it hits
    let [t, x, y, z] = mray(0, ...mouse_ray())
    hover = t ? group(x, y, z) : []
    if (btnp(19)) {
      if (hover.length >= 2) pop(hover)
      else sfx(2)
    }
  }

  for (let p of parts) { p.x += p.vx; p.y += p.vy; p.z += p.vz; p.vy -= 0.008; p.life-- }
  parts = parts.filter((p) => p.life > 0)
  for (let p of pops) { p.y -= 0.5; p.life-- }
  pops = pops.filter((p) => p.life > 0)
}

function _draw() {
  let cx = W / 2, cy = H / 2 - 0.5, cz = D / 2, r = 9.5
  cam_set_pos([cx + sin(ang) * cos(lift) * r, cy + sin(lift) * r, cz + cos(ang) * cos(lift) * r])
  cam_set_lookat([cx, cy, cz])

  outline(0)
  map(0)
  map(1)
  // light up the group under the cursor: slightly bigger cubes in a lighter shade, outlined in white
  if (hover.length >= 2) {
    outline(7)
    let c = LIGHT[mget(0, ...hover[0])]
    for (let [x, y, z] of hover) cube(x + 0.5, y + 0.5, z + 0.5, 1.04, c)
  }
  outline()
  for (let p of parts) cube(p.x, p.y, p.z, 0.15 * p.life / 40 + 0.05, p.c)

  print('Score ' + score, 4, 4, 7, 0)
  let b = 'Best ' + best
  print(b, 252 - b.length * 7, 4, 10, 0)
  for (let p of pops) print(p.text, p.x - 6, p.y - 14, 10, 0)
  if (over) {
    rectfill(40, 96, 215, 158, 1)
    rect(40, 96, 215, 158, 7)
    print('No more moves!', 79, 104, 10, 0)
    let s = 'Score ' + score + (score >= best && score > 0 ? '  New best!' : '')
    print(s, 128 - s.length * 3.5, 120, 7, 0)
    print('click or O to play again', 44, 138, 6)
  } else {
    print('Click a group of 2+ to pop it', 4, 232, 6, 0)
    print('Arrows turn the camera', 4, 244, 6, 0)
  }
}

